B.a2h=new A.ag("1. \u60a8\u4e0d\u5f97\u5229\u7528\u672c\u670d\u52a1\u5236\u4f5c\u3001\u590d\u5236\u3001\u53d1\u5e03\u3001\u4f20\u64ad\u542b\u6709\u4e0b\u5217\u5185\u5bb9\u7684\u4fe1\u606f:\u53cd\u5bf9\u5baa\u6cd5\u786e\u5b9a\u7684\u57fa\u672c\u539f\u5219\u7684;\u5371\u5bb3\u56fd\u5bb6\u5b89\u5168,\u6cc4\u9732\u56fd\u5bb6\u79d8\u5bc6,\u98a0\u8986\u56fd\u5bb6\u653f\u6743,\u7834\u574f\u56fd\u5bb6\u7edf\u4e00\u7684;\u635f\u5bb3\u56fd\u5bb6\u8363\u8a89\u548c\u5229\u76ca\u7684;\u6b6a\u66f2\u3001\u4e11\u5316\u3001\u4eb5\u6e0e\u3001\u5426\u5b9a\u82f1\u96c4\u70c8\u58eb\u4e8b\u8ff9\u548c\u7cbe\u795e\u7684;\u5ba3\u626c\u6050\u6016\u4e3b\u4e49\u3001\u6781\u7aef\u4e3b\u4e49\u6216\u8005\u717d\u52a8\u5b9e\u65bd\u6050\u6016\u6d3b\u52a8\u3001\u6781\u7aef\u4e3b\u4e49\u6d3b\u52a8\u7684;\u717d\u52a8\u6c11\u65cf\u4ec7\u6068\u3001\u6c11\u65cf\u6b67\u89c6,\u7834\u574f\u6c11\u65cf\u56e2\u7ed3\u7684;\u7834\u574f\u56fd\u5bb6\u5b97\u6559\u653f\u7b56,\u5ba3\u626c\u90aa\u6559\u548c\u5c01\u5efa\u8ff7\u4fe1\u7684;\u6563\u5e03\u8c23\u8a00,\u6270\u4e71\u7ecf\u6d4e\u79e9\u5e8f\u548c\u793e\u4f1a\u79e9\u5e8f\u7684;\u6563\u5e03\u6deb\u79fd\u3001\u8272\u60c5\u3001\u8d4c\u535a\u3001\u66b4\u529b\u3001\u51f6\u6740\u3001\u6050\u6016\u6216\u8005\u6559\u5506\u72af\u7f6a\u7684;\u4fae\u8fb1\u6216\u8005\u8bfd\u8c24\u4ed6\u4eba,\u4fb5\u5bb3\u4ed6\u4eba\u540d\u8a89\u3001\u9690\u79c1\u548c\u5176\u4ed6\u5408\u6cd5\u6743\u76ca\u7684;\u6cd5\u5f8b\u3001\u884c\u653f\u6cd5\u89c4\u7981\u6b62\u7684\u5176\u4ed6\u5185\u5bb9\u3002",!0)
B.a2q=new A.ag("2. \u60a8\u5e94\u5f53\u9632\u8303\u548c\u62b5\u5236\u5236\u4f5c\u3001\u590d\u5236\u3001\u53d1\u5e03\u542b\u6709\u4e0b\u5217\u5185\u5bb9\u7684\u4e0d\u826f\u4fe1\u606f:\u4f7f\u7528\u5938\u5f20\u6807\u9898,\u5185\u5bb9\u4e0e\u6807\u9898\u4e25\u91cd\u4e0d\u7b26\u7684;\u7092\u4f5c\u7eef\u95fb\u3001\u4e11\u95fb\u3001\u52a3\u8ff9\u7684;\u4e0d\u5f53\u8bc4\u8ff0\u81ea\u7136\u707e\u5bb3\u3001\u91cd\u5927\u4e8b\u6545\u7b49\u707e\u96be\u7684;\u5e26\u6709\u6027\u6697\u793a\u3001\u6027\u6311\u9017\u7b49\u6613\u4f7f\u4eba\u4ea7\u751f\u6027\u8054\u60f3\u7684;\u5c55\u73b0\u8840\u8165\u3001\u60ca\u609a\u3001\u6b8b\u5fcd\u7b49\u81f4\u4eba\u8eab\u5fc3\u4e0d\u9002\u7684;\u717d\u52a8\u4eba\u7fa4\u6b67\u89c6\u3001\u5730\u57df\u6b67\u89c6\u7684;\u5ba3\u626c\u4f4e\u4fd7\u3001\u5eb8\u4fd7\u3001\u5a9a\u4fd7\u5185\u5bb9\u7684;\u53ef\u80fd\u5f15\u53d1\u672a\u6210\u5e74\u4eba\u6a21\u4eff\u4e0d\u5b89\u5168\u884c\u4e3a\u548c\u8fdd\u53cd\u793e\u4f1a\u516c\u5fb7\u884c\u4e3a\u3001\u8bf1\u5bfc\u672a\u6210\u5e74\u4eba\u4e0d\u826f\u55dc\u597d\u7684;\u5176\u4ed6\u5bf9\u7f51\u7edc\u751f\u6001\u9020\u6210\u4e0d\u826f\u5f71\u54cd\u7684\u5185\u5bb9\u3002",!1)
B.a1H=new A.ag("3. \u4e09\u7ef4\u4f5c\u54c1\u7684\u7279\u522b\u89c4\u8303:\u62cd\u6444\u5e76\u516c\u5f00\u53d1\u5e03\u6d89\u53ca\u4ed6\u4eba\u4f4f\u5b85\u3001\u529e\u516c\u573a\u6240\u7b49\u975e\u516c\u5f00\u7a7a\u95f4\u7684\u4e09\u7ef4\u91cd\u5efa,\u5e94\u5f53\u4e8b\u5148\u53d6\u5f97\u6743\u5229\u4eba\u540c\u610f;\u753b\u9762\u6216\u70b9\u4e91\u4e2d\u53ef\u8bc6\u522b\u5230\u7279\u5b9a\u4ed6\u4eba\u7684,\u5e94\u5f53\u53d6\u5f97\u8be5\u4ed6\u4eba\u540c\u610f\u3002\u4e0d\u5f97\u53d1\u5e03\u6d89\u53ca\u56fd\u5bb6\u5b89\u5168\u654f\u611f\u533a\u57df\u3001\u519b\u4e8b\u8bbe\u65bd\u7b49\u6cd5\u5f8b\u6cd5\u89c4\u7981\u6b62\u6d4b\u7ed8\u3001\u62cd\u6444\u573a\u6240\u7684\u4e09\u7ef4\u91cd\u5efa\u3002",!1)
B.a3b=new A.ag("4. \u60a8\u4e0d\u5f97\u4ece\u4e8b\u4e0b\u5217\u884c\u4e3a:\u5229\u7528\u6280\u672f\u624b\u6bb5\u6279\u91cf\u6ce8\u518c\u8d26\u53f7;\u5bf9\u672c\u4ea7\u54c1\u8fdb\u884c\u53cd\u5411\u5de5\u7a0b\u3001\u7834\u89e3\u6216\u7ed5\u8fc7\u6280\u672f\u4fdd\u62a4\u63aa\u65bd(\u6cd5\u5f8b\u6cd5\u89c4\u5141\u8bb8\u7684\u9664\u5916);\u672a\u7ecf\u6388\u6743\u6293\u53d6\u3001\u4e0b\u8f7d\u3001\u590d\u5236\u5176\u4ed6\u7528\u6237\u7684\u4f5c\u54c1\u7528\u4e8e\u672c\u670d\u52a1\u4e4b\u5916\u7684\u7528\u9014;\u4ee5\u81ea\u52a8\u5316\u624b\u6bb5\u9ad8\u9891\u8c03\u7528\u672c\u670d\u52a1\u6216\u91c7\u96c6\u6570\u636e;\u5e72\u6270\u3001\u7834\u574f\u672c\u670d\u52a1\u7684\u6b63\u5e38\u8fd0\u884c;\u5236\u4f5c\u3001\u4f20\u64ad\u75c5\u6bd2\u3001\u6728\u9a6c\u7b49\u6076\u610f\u7a0b\u5e8f,\u6216\u672a\u7ecf\u6388\u6743\u8bbf\u95ee\u5e73\u53f0\u7cfb\u7edf\u3001\u4ed6\u4eba\u8d26\u53f7;\u53d1\u5e03\u5783\u573e\u4fe1\u606f\u3001\u6076\u610f\u8425\u9500\u4fe1\u606f;\u4ee5\u5e73\u53f0\u540d\u4e49\u884c\u4e8b,\u6216\u5bf9\u5916\u5ba3\u79f0\u4e0e\u5e73\u53f0\u5b58\u5728\u5408\u4f5c\u3001\u4ee3\u7406\u7b49\u5173\u7cfb\u8bef\u5bfc\u4ed6\u4eba\u3002",!1)
B.a1m=new A.ag("5. \u4e09\u7ef4\u62cd\u6444\u9700\u8981\u60a8\u5728\u73b0\u573a\u79fb\u52a8\u3002\u8bf7\u6ce8\u610f\u5468\u56f4\u73af\u5883\u4e0e\u81ea\u8eab\u53ca\u4ed6\u4eba\u5b89\u5168,\u4e0d\u8981\u5728\u9053\u8def\u3001\u9ad8\u5904\u8fb9\u7f18\u7b49\u5371\u9669\u73af\u5883\u4e2d\u62cd\u6444\u3002",!1)
B.a4V=s([B.a2h,B.a2q,B.a1H,B.a3b,B.a1m],t.Q)
B.a3E=new A.ed("\u56db\u3001\u7528\u6237\u884c\u4e3a\u89c4\u8303",B.a4V)
B.a1F=new A.ag("1. \u5148\u5ba1\u540e\u53d1:\u60a8\u53d1\u5e03\u7684\u4f5c\u54c1\u9700\u7ecf\u5e73\u53f0\u5ba1\u6838,\u5ba1\u6838\u901a\u8fc7\u540e\u624d\u4f1a\u51fa\u73b0\u5728\u793e\u533a\u5e7f\u573a;\u5ba1\u6838\u671f\u95f4\u4f5c\u54c1\u5bf9\u5176\u4ed6\u7528\u6237\u4e0d\u53ef\u89c1,\u60a8\u53ef\u4ee5\u7533\u8bf7\u64a4\u56de\u6216\u5220\u9664\u3002\u79c1\u6709\u4e91\u5907\u4efd\u4e0d\u4f1a\u56e0\u4e0a\u4f20\u800c\u81ea\u52a8\u53d8\u6210\u516c\u5f00\u4f5c\u54c1\u3002",!1)
B.a2I=new A.ag("\u5ba1\u6838\u65b9\u5f0f:\u9488\u5bf9\u6700\u7ec8 GLB,\u5e73\u53f0\u751f\u6210 26 \u5f20\u591a\u89d2\u5ea6\u6a21\u578b\u6e32\u67d3\u56fe,\u59d4\u6258\u963f\u91cc\u4e91\u8fdb\u884c\u6807\u9898\u3001\u63cf\u8ff0\u7684\u6587\u5b57\u5ba1\u6838\u53ca\u5ba1\u6838\u56fe\u7684\u56fe\u7247\u5ba1\u6838\u3002\u8be5\u6d41\u7a0b\u4e0d\u8981\u6c42\u4e0a\u4f20\u539f\u59cb\u62cd\u6444\u7167\u7247\u6216\u62cd\u6444\u8fc7\u7a0b\u6570\u636e\u3002\u673a\u5ba1\u98ce\u9669\u53ef\u8f6c\u4eba\u5de5\u590d\u6838,\u660e\u786e\u8fdd\u89c4\u4e0d\u4e88\u53d1\u5e03,\u670d\u52a1\u5f02\u5e38\u6216\u7ed3\u679c\u4e0d\u5b8c\u6574\u65f6\u4e0d\u4e88\u81ea\u52a8\u516c\u5f00\u3002\u6682\u4e0d\u652f\u6301\u7684\u683c\u5f0f\u4e0d\u80fd\u901a\u8fc7\u8be5\u6d41\u7a0b\u81ea\u52a8\u516c\u5f00;\u4fee\u6539\u5df2\u63d0\u4ea4\u7684\u4f5c\u54c1\u5185\u5bb9\u9700\u8981\u91cd\u65b0\u5ba1\u6838\u3002",!1)
B.a2g=new A.ag("2. \u53d1\u5e03\u5373\u516c\u5f00:\u4f5c\u54c1\u901a\u8fc7\u5ba1\u6838\u540e,\u4f5c\u54c1\u5185\u5bb9\u3001\u60a8\u7684\u6635\u79f0\u3001\u8d26\u53f7 ID \u53ca\u53d1\u5e03\u65f6\u7684 IP \u5c5e\u5730\u5c06\u5bf9\u6240\u6709\u7528\u6237(\u542b\u672a\u767b\u5f55\u8bbf\u5ba2)\u516c\u5f00\u53ef\u89c1\u3002\u516c\u5f00\u53d1\u5e03\u4e0d\u7b49\u4e8e\u653e\u5f03\u9690\u79c1\u6216\u4e2a\u4eba\u4fe1\u606f\u6743\u76ca,\u4e5f\u4e0d\u514d\u9664\u53d1\u5e03\u8005\u53d6\u5f97\u4ed6\u4eba\u6388\u6743\u7684\u4e49\u52a1\u3002IP \u5c5e\u5730\u5c55\u793a\u662f\u6cd5\u5b9a\u8981\u6c42,\u65e0\u6cd5\u5173\u95ed,\u8be6\u89c1\u300a\u65b9\u5bf8\u95f4\u9690\u79c1\u653f\u7b56\u300b\u3002",!0)
B.a32=new A.ag('3. \u672c\u534f\u8bae\u6240\u79f0"\u5185\u5bb9"\u5305\u62ec\u60a8\u5728\u672c\u670d\u52a1\u4e2d\u4e0a\u4f20\u3001\u53d1\u5e03\u7684\u4e09\u7ef4\u6a21\u578b(\u5982 GLB \u7f51\u683c mesh\u3001PLY \u70b9\u4e91)\u3001\u4e09\u7ef4\u91cd\u5efa\u6570\u636e\u3001\u5c01\u9762\u548c\u884d\u751f\u5ba1\u6838\u56fe\u3001\u6807\u9898\u3001\u63cf\u8ff0\u3001\u8d26\u53f7\u8d44\u6599\u4ee5\u53ca\u5176\u4ed6\u4efb\u4f55\u4fe1\u606f\u3002',!1)
B.a2L=new A.ag("4. \u60a8\u5bf9\u53d1\u5e03\u7684\u5185\u5bb9\u72ec\u7acb\u627f\u62c5\u5168\u90e8\u6cd5\u5f8b\u8d23\u4efb\u3002\u60a8\u4fdd\u8bc1\u5bf9\u53d1\u5e03\u7684\u5185\u5bb9\u4eab\u6709\u5408\u6cd5\u6743\u5229\u6216\u5df2\u53d6\u5f97\u5408\u6cd5\u6388\u6743;\u56e0\u60a8\u53d1\u5e03\u7684\u5185\u5bb9\u5f15\u53d1\u7b2c\u4e09\u65b9\u4e3b\u5f20\u6743\u5229,\u5bfc\u81f4\u5e73\u53f0\u906d\u53d7\u635f\u5931\u7684,\u60a8\u5e94\u5f53\u8d54\u507f\u3002",!1)
B.a3i=new A.ag("\u5220\u9664\u3001\u64a4\u56de\u4e0e\u8bc1\u636e\u7559\u5b58:\u505c\u6b62\u516c\u5f00\u4e0d\u7b49\u4e8e\u6240\u6709\u526f\u672c\u5373\u65f6\u7269\u7406\u64e6\u9664\u3002\u5ba1\u6838\u6750\u6599\u3001\u6295\u8bc9\u7533\u8bc9\u8bc1\u636e\u3001\u6cd5\u5b9a\u7559\u5b58\u53ca\u5386\u53f2\u5907\u4efd\u7684\u9650\u5236\u5904\u7406\u548c\u6e05\u7406,\u6309\u300a\u65b9\u5bf8\u95f4\u9690\u79c1\u653f\u7b56\u300b\u7b2c\u56db\u7ae0\u6267\u884c;\u76f8\u5173\u526f\u672c\u4e0d\u80fd\u56e0\u5907\u4efd\u6062\u590d\u800c\u91cd\u65b0\u516c\u5f00\u3002",!1)
B.a1S=new A.ag("5. \u7b2c\u4e09\u65b9\u5c31\u60a8\u53d1\u5e03\u7684\u5185\u5bb9\u5411\u5e73\u53f0\u4e3b\u5f20\u6743\u5229\u65f6,\u5e73\u53f0\u6709\u6743\u4f9d\u6cd5\u5148\u884c\u4e0b\u67b6\u76f8\u5173\u5185\u5bb9\u5e76\u901a\u77e5\u60a8;\u60a8\u53ef\u6309\u7b2c\u516b\u7ae0\u7684\u6e20\u9053\u63d0\u4ea4\u4e0d\u4fb5\u6743\u58f0\u660e\u4e0e\u6743\u5229\u8bc1\u660e\u8fdb\u884c\u7533\u8bc9\u3002",!1)
B.akc=s([B.a1F,B.a2I,B.a2g,B.a32,B.a2L,B.a3i,B.a1S],t.Q)
B.a3H=new A.ed("\u4e94\u3001\u5185\u5bb9\u53d1\u5e03\u4e0e\u5ba1\u6838",B.akc)
B.a2E=new A.ag("1. \u5e73\u53f0\u8f6f\u4ef6\u53ca\u5176\u6240\u542b\u7684\u754c\u9762\u8bbe\u8ba1\u3001\u7a0b\u5e8f\u4ee3\u7801\u3001\u5546\u6807\u6807\u8bc6\u7b49\u77e5\u8bc6\u4ea7\u6743\u5f52\u6211\u4eec\u6216\u76f8\u5e94\u6743\u5229\u4eba\u6240\u6709\u3002\u672a\u7ecf\u8bb8\u53ef,\u60a8\u4e0d\u5f97\u590d\u5236\u3001\u4fee\u6539\u3001\u4f20\u64ad\u6216\u7528\u4e8e\u4efb\u4f55\u5546\u4e1a\u76ee\u7684\u3002",!1)
B.a2b=new A.ag("2. \u60a8\u5728\u672c\u670d\u52a1\u4e2d\u4e0a\u4f20\u6216\u53d1\u5e03\u7684\u4f5c\u54c1(\u542b\u4e09\u7ef4\u70b9\u4e91\u3001\u7f51\u683c\u6a21\u578b\u53ca\u5176\u884d\u751f\u7684\u5c01\u9762\u4e0e\u5ba1\u6838\u56fe)\u7684\u77e5\u8bc6\u4ea7\u6743\u5f52\u60a8\u6216\u4f9d\u6cd5\u4eab\u6709\u6743\u5229\u7684\u6743\u5229\u4eba\u6240\u6709,\u4e0d\u56e0\u53d1\u5e03\u884c\u4e3a\u800c\u8f6c\u79fb\u3002",!0)
B.a1s=new A.ag("3. \u4e3a\u5411\u60a8\u63d0\u4f9b\u670d\u52a1\u5e76\u6539\u8fdb\u4ea7\u54c1,\u60a8\u6388\u4e88\u5e73\u53f0\u4e00\u9879\u5168\u7403\u8303\u56f4\u5185\u3001\u514d\u8d39\u3001\u975e\u72ec\u5bb6\u7684\u8bb8\u53ef,\u5305\u62ec\u5bf9\u5185\u5bb9\u7684\u590d\u5236\u6743\u3001\u4fe1\u606f\u7f51\u7edc\u4f20\u64ad\u6743\u3001\u6539\u7f16\u6743\u3001\u6c47\u7f16\u6743\u3001\u5c55\u793a\u6743\u53ca\u5236\u4f5c\u884d\u751f\u5185\u5bb9\u7684\u6743\u5229\u3002\u672c\u6b3e\u6240\u79f0\u5185\u5bb9,\u6307\u60a8\u4e0a\u4f20\u81f3\u672c\u670d\u52a1\u7684\u5185\u5bb9,\u5305\u62ec\u53d1\u5e03\u5230\u793e\u533a\u5e7f\u573a\u7684\u4f5c\u54c1,\u4ee5\u53ca\u79c1\u6709\u4e91\u5907\u4efd(\u4e91\u7aef\u5b58\u50a8)\u529f\u80fd\u4e2d\u60a8\u5b58\u50a8\u7684\u5185\u5bb9,\u542b\u4e09\u7ef4\u70b9\u4e91\u3001\u7f51\u683c\u6a21\u578b\u3001\u5c01\u9762\u3001\u884d\u751f\u5ba1\u6838\u56fe\u3001\u6807\u9898\u3001\u63cf\u8ff0\u3002\u4e0a\u8ff0\u6743\u5229\u4ec5\u7528\u4e8e:(1)\u8fd0\u8425\u6240\u5fc5\u9700:\u5b58\u50a8\u3001\u5907\u4efd\u3001\u4f20\u8f93\u3001\u5206\u53d1\u3001\u516c\u5f00\u5c55\u793a(\u4ec5\u9650\u60a8\u9009\u62e9\u516c\u5f00\u53d1\u5e03\u7684\u5185\u5bb9)\u53ca\u683c\u5f0f\u9002\u914d\u3001\u751f\u6210\u5ba1\u6838\u56fe\u3001\u6587\u5b57\u4e0e\u56fe\u7247\u5185\u5bb9\u5b89\u5168\u68c0\u6d4b\u7b49\u6280\u672f\u5904\u7406,\u5e76\u53ef\u5c06\u76f8\u5e94\u5904\u7406\u59d4\u6258\u7ed9\u53d7\u7ea6\u675f\u7684\u4e91\u670d\u52a1\u548c\u5185\u5bb9\u5ba1\u6838\u670d\u52a1\u5546\u6267\u884c;(2)\u5c06\u60a8\u5df2\u516c\u5f00\u53d1\u5e03\u7684\u4f5c\u54c1\u7528\u4e8e\u672c\u4ea7\u54c1\u5404\u7ec8\u7aef\u7248\u672c\u53ca\u5e94\u7528\u5546\u5e97\u9875\u9762\u7684\u5c55\u793a\u4e0e\u63a8\u4ecb;(3)\u6211\u4eec\u5185\u90e8\u7684\u79d1\u5b66\u7814\u7a76\u3001\u6280\u672f\u5f00\u53d1\u4e0e\u6539\u8fdb,\u5305\u62ec\u4f46\u4e0d\u9650\u4e8e\u5404\u7c7b\u4eba\u5de5\u667a\u80fd\u7b97\u6cd5\u4e0e\u6a21\u578b\u7684\u8bad\u7ec3\u3001\u8bc4\u6d4b\u4e0e\u4f18\u5316(\u5982\u4e09\u7ef4\u91cd\u5efa\u76f8\u5173\u7b97\u6cd5\u4e0e\u6a21\u578b),\u4e0d\u8bba\u91c7\u7528\u73b0\u5728\u5df2\u77e5\u6216\u65e5\u540e\u5f00\u53d1\u7684\u6280\u672f\u4e0e\u5f62\u5f0f\u3002",!0)
B.a1W=new A.ag("4. \u5bf9\u5916\u63d0\u4f9b\u7814\u7a76\u6570\u636e:\u6211\u4eec\u5982\u9700\u5728\u5b66\u672f\u8bba\u6587\u3001\u516c\u5f00\u6570\u636e\u96c6\u6216\u79d1\u7814\u5408\u4f5c\u4e2d\u5bf9\u5916\u63d0\u4f9b\u7814\u7a76\u6570\u636e,\u4ec5\u4f7f\u7528\u7ecf\u533f\u540d\u5316\u5904\u7406\u3001\u65e0\u6cd5\u8bc6\u522b\u60a8\u7684\u8eab\u4efd\u4e14\u4e0d\u80fd\u590d\u539f\u7684\u6570\u636e;\u9700\u8981\u4ee5\u53ef\u8bc6\u522b\u60a8\u8eab\u4efd\u7684\u5f62\u5f0f\u5bf9\u5916\u63d0\u4f9b\u7684,\u6211\u4eec\u5c06\u53e6\u884c\u5f81\u5f97\u60a8\u7684\u5355\u72ec\u540c\u610f\u3002",!0)
B.a1t=new A.ag("5. \u8bb8\u53ef\u7684\u671f\u9650\u4e0e\u7ec8\u6b62:\u4e0a\u8ff0\u8bb8\u53ef\u81ea\u5185\u5bb9\u4e0a\u4f20\u65f6\u751f\u6548\u3002\u60a8\u5220\u9664\u76f8\u5e94\u5185\u5bb9,\u6216\u6ce8\u9500\u8d26\u53f7(\u6307\u60a8\u4f9d\u7167\u7b2c\u4e09\u7ae0\u7b2c 5 \u6761\u53ca\u300a\u65b9\u5bf8\u95f4\u9690\u79c1\u653f\u7b56\u300b\u7b2c\u516d\u7ae0,\u4e3b\u52a8\u7533\u8bf7\u5220\u9664\u8d26\u53f7\u53ca\u5176\u9879\u4e0b\u4e2a\u4eba\u4fe1\u606f\u7684\u884c\u4e3a)\u540e,\u9664\u6cd5\u5f8b\u6cd5\u89c4\u53e6\u6709\u89c4\u5b9a\u6216\u672c\u534f\u8bae\u53e6\u6709\u7ea6\u5b9a(\u5982\u4f9d\u6cd5\u4e0b\u67b6\u5185\u5bb9\u7684\u5c01\u5b58\u7559\u5b58)\u5916,\u8bb8\u53ef\u5373\u544a\u7ec8\u6b62,\u6211\u4eec\u5c06\u505c\u6b62\u5728\u65b0\u7684\u7814\u7a76\u4e0e\u6a21\u578b\u8bad\u7ec3\u4e2d\u4f7f\u7528\u8be5\u5185\u5bb9;\u4f46\u5728\u6b64\u4e4b\u524d\u5df2\u5b8c\u6210\u7684\u7814\u7a76\u6210\u679c\u4e0e\u5df2\u8bad\u7ec3\u5b8c\u6210\u7684\u6a21\u578b\u4e0d\u53d7\u5f71\u54cd\u3002",!0)
B.a1C=new A.ag("6. \u4e3a\u66f4\u597d\u5730\u4fdd\u62a4\u60a8\u7684\u6743\u76ca,\u60a8\u540c\u610f\u5e73\u53f0\u6709\u6743\u81ea\u884c\u6216\u59d4\u6258\u7b2c\u4e09\u65b9,\u5bf9\u60a8\u4e0a\u4f20\u53d1\u5e03\u4e14\u4eab\u6709\u77e5\u8bc6\u4ea7\u6743\u7684\u5185\u5bb9\u906d\u53d7\u7b2c\u4e09\u65b9\u4fb5\u6743\u7684\u884c\u4e3a\u8fdb\u884c\u7ef4\u6743,\u5f62\u5f0f\u5305\u62ec\u4f46\u4e0d\u9650\u4e8e\u76d1\u6d4b\u4fb5\u6743\u884c\u4e3a\u3001\u53d1\u9001\u7ef4\u6743\u51fd\u3001\u63d0\u8d77\u8bc9\u8bbc\u6216\u4ef2\u88c1\u3001\u8c03\u89e3\u3001\u548c\u89e3\u7b49\u3002\u60a8\u53ef\u4ee5\u968f\u65f6\u4e66\u9762\u901a\u77e5\u5e73\u53f0\u64a4\u56de\u672c\u6b3e\u7ef4\u6743\u6388\u6743\u3002",!1)
B.a20=new A.ag("7. \u60a8\u8ba4\u4e3a\u672c\u670d\u52a1\u4e2d\u7684\u5185\u5bb9\u4fb5\u72af\u60a8\u7684\u5408\u6cd5\u6743\u76ca\u7684,\u53ef\u6309\u7b2c\u516b\u7ae0\u7684\u6e20\u9053\u901a\u77e5\u6211\u4eec,\u5e76\u63d0\u4f9b\u6743\u5c5e\u8bc1\u660e\u4e0e\u521d\u6b65\u4fb5\u6743\u8bc1\u636e;\u6211\u4eec\u5c06\u4f9d\u6cd5\u53ca\u65f6\u5904\u7406\u3002",!1)
B.a1h=new A.ag("8. \u5e73\u53f0\u5728\u5f00\u53d1\u3001\u8fd0\u8425\u672c\u670d\u52a1\u8fc7\u7a0b\u4e2d\u4ea7\u751f\u7684\u3001\u4e0d\u5305\u542b\u60a8\u4f5c\u54c1\u5185\u5bb9\u672c\u8eab\u7684\u6570\u636e\u4e0e\u6210\u679c(\u5982\u7edf\u8ba1\u6570\u636e\u3001\u65e5\u5fd7\u3001\u7ecf\u533f\u540d\u5316\u5904\u7406\u7684\u5206\u6790\u7ed3\u679c\u3001\u7b97\u6cd5\u4e0e\u6a21\u578b\u53c2\u6570\u3001\u7814\u7a76\u6210\u679c),\u7531\u5e73\u53f0\u5728\u6cd5\u5f8b\u6cd5\u89c4\u5141\u8bb8\u7684\u8303\u56f4\u5185\u4eab\u6709\u6743\u5229\u3002\u672c\u6761\u4e0d\u6539\u53d8\u7b2c 2 \u6761\u7ea6\u5b9a\u7684\u4f5c\u54c1\u5f52\u5c5e\u3002",!1)
